function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(60001);
var T0=Date.now();
var C=5,RC=20,P=0.9;
var passed=0;
for(var r=0;r<RC;r++){var ok=true;for(var c=0;c<C;c++)if(R()>P){ok=false;break;}if(ok)passed++;}
console.log(JSON.stringify({id:"JAH-APX60-000001",ok:true,metrics:{checks:C,candidates:RC,passed:passed,blocked:RC-passed,pass_rate:+(passed/RC).toFixed(3)},ms:Date.now()-T0}));

